<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {api} from '../lib/api';
import {type RiskSettings,ruleNames} from '../lib/risk';
import Icon from './Icon.vue';
import RiskCustomerEditor from './RiskCustomerEditor.vue';
const emit=defineEmits<{back:[];saved:[];toast:[message:string]}>();
const cfg=ref<RiskSettings>(),defaults=ref<RiskSettings>(),error=ref(''),busy=ref(false),loading=ref(true),customer=ref(false),proxies=ref('');
const large=computed({get:()=>Number(cfg.value?.large_adjustment||0)/100,set:(v:number)=>{if(cfg.value)cfg.value.large_adjustment=Math.round(Number(v)*100)}});
const fields:{key:keyof RiskSettings;label:string;min:number;max:number}[]=[
 {key:'retention_days',label:'事件及访问统计保存天数',min:1,max:365},{key:'refresh_seconds',label:'监控页面刷新间隔（秒）',min:5,max:300},{key:'scan_seconds',label:'后台异常检查间隔（秒）',min:10,max:3600},
 {key:'behavior_window_seconds',label:'异常行为统计窗口（秒）',min:60,max:86400},{key:'login_source_accounts',label:'同一已核实来源尝试账号数',min:2,max:10000},{key:'duplicate_count',label:'窗口内重复提交告警次数',min:1,max:10000},
 {key:'cancel_count',label:'窗口内撤回告警次数',min:1,max:10000},{key:'failure_min_count',label:'计算失败比例的最少结束申请数',min:1,max:10000},{key:'failure_percent',label:'未完成比例告警（%）',min:1,max:100},
 {key:'queue_count',label:'单客户排队数量告警',min:1,max:100000},{key:'queue_seconds',label:'排队时长告警（秒）',min:60,max:604800},{key:'processing_seconds',label:'办理时长告警（秒）',min:60,max:604800},
];
async function load(){loading.value=true;error.value='';try{const result=await api<{settings:RiskSettings;defaults:RiskSettings}>('/api/admin/risk-settings');cfg.value=result.settings;defaults.value=result.defaults;proxies.value=result.settings.trusted_proxies.join('\n')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function restore(){if(!cfg.value||!defaults.value)return;const revision=cfg.value.revision;cfg.value=JSON.parse(JSON.stringify(defaults.value));cfg.value!.revision=revision;proxies.value='';emit('toast','已填入推荐默认值，保存后才生效')}
async function save(){if(!cfg.value)return;busy.value=true;error.value='';try{cfg.value.trusted_proxies=proxies.value.split(/[\n,]+/).map(s=>s.trim()).filter(Boolean);await api('/api/admin/risk-settings',{method:'PUT',body:JSON.stringify(cfg.value)});await load();emit('saved');emit('toast','风控配置已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function setNumber(key:keyof RiskSettings,event:Event){if(cfg.value)(cfg.value as unknown as Record<string,unknown>)[key]=Number((event.target as HTMLInputElement).value)}
onMounted(load);
</script>
<template><section class="risk-settings"><header class="risk-settings-heading"><div><p class="eyebrow">RISK SETTINGS</p><h2>风控配置</h2><p class="muted">按业务类型独立控制，调整后对后续请求生效。</p></div><button class="button secondary" :disabled="busy" @click="emit('back')"><Icon name="ArrowLeft"/>返回监控</button></header>
 <p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="loading&&!cfg">正在读取配置…</p>
 <form v-if="cfg" @submit.prevent="save"><fieldset :disabled="busy||loading">
 <section class="table-card risk-section"><h3>记录与处理模式</h3><label class="risk-check"><input v-model="cfg.enabled" type="checkbox"/>记录风控事件、访问统计并检查业务异常</label><p class="field-help">关闭记录不会关闭下方已设为“执行限制”的规则。风控管理员仍可进入本页解除限制；不会停止已受理申请。</p></section>
 <section class="table-card risk-section"><h3>接口限流规则</h3><p class="field-help">登录按账号计数；业务访问同时检查客户总量、接口类型及 API 密钥。仅告警会放行请求。修改某条规则会重置该规则已有计数及限制。</p>
 <div class="table-scroll"><table><thead><tr><th>规则</th><th>处理方式</th><th>窗口（秒）</th><th>最大次数</th><th>触发后限制（秒）</th></tr></thead><tbody><tr v-for="(name,key) in ruleNames" :key="key"><td>{{name}}</td><td><select v-model="cfg.rules[key]!.mode" :aria-label="`${name}处理方式`"><option value="off">关闭</option><option value="observe">仅告警</option><option value="enforce">执行限制</option></select></td><td><input v-model.number="cfg.rules[key]!.window_seconds" :aria-label="`${name}窗口秒数`" type="number" min="1" max="86400" required/></td><td><input v-model.number="cfg.rules[key]!.limit" :aria-label="`${name}最大次数`" type="number" min="1" max="100000" required/></td><td><input v-model.number="cfg.rules[key]!.cooldown_seconds" :aria-label="`${name}限制秒数`" type="number" min="1" max="86400" required/></td></tr></tbody></table></div></section>
 <section class="table-card risk-section"><h3>告警阈值与记录周期</h3><p class="field-help">业务异常只提示关注，不自动终止申请或改动积分。降低保存天数会在下次后台检查时清理超期风控记录，业务申请和账单保留。</p><div class="risk-fields"><label v-for="f in fields" :key="f.key">{{f.label}}<input :value="cfg[f.key]" :aria-label="f.label" @input="setNumber(f.key,$event)" type="number" :min="f.min" :max="f.max" required/></label><label>大额积分调整告警（积分，1 分 = 1 R）<input v-model.number="large" aria-label="大额积分调整告警" type="number" min="1" max="1000000" step="0.01" required/></label></div><label class="risk-check"><input v-model="cfg.finance_checks" type="checkbox"/>检查冻结金额、申请结算与账单一致性</label></section>
 <section class="table-card risk-section"><h3>来源识别</h3><label>可信代理 IP / 网段（每行一项）<textarea v-model="proxies" aria-label="可信代理地址" rows="4" placeholder="仅填写已核实的反向代理地址，默认留空"/></label><p class="field-help">只有来自可信代理的转发链会用于确认客户 IP；未核实的来源会明确标注，不用于跨账号来源告警。来源 IP 不参与账号封禁，避免共用出口误伤。</p></section>
 <section class="table-card risk-section"><h3>客户独立配置</h3><p class="field-help">可覆盖某位客户的次数，或仅暂停其新申请。已受理任务、查询、撤回保持可用。</p><button type="button" class="button secondary" @click="customer=true">配置指定客户</button></section>
 <footer class="risk-save"><button class="button secondary" type="button" @click="restore">填入推荐默认值</button><button class="button primary" type="submit">{{busy?'保存中…':'保存风控配置'}}</button></footer>
 </fieldset></form><RiskCustomerEditor v-if="customer" @close="customer=false" @saved="customer=false;emit('toast','客户风控规则已保存')"/>
</section></template>
<style scoped>.risk-settings{min-width:0}.risk-settings-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.risk-settings h2{font-size:24px;margin:8px 0}.risk-settings h3{font-size:16px;margin:0 0 15px}.risk-settings .muted{font-size:12px}.risk-settings fieldset{border:0;padding:0;min-width:0;display:grid;gap:18px}.risk-section{padding:22px;margin:0;min-width:0}.risk-section .field-help{line-height:1.8;margin-bottom:16px}.risk-section label{display:grid;gap:8px;font-size:12px}.risk-section .risk-check{display:flex;align-items:center;gap:8px;margin-top:16px}.risk-section input,.risk-section select{min-width:0}.risk-section table{min-width:750px}.risk-section table input{width:110px}.risk-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.risk-save{display:flex;justify-content:flex-end;gap:12px;padding-bottom:24px}.risk-section textarea{width:100%;resize:vertical}@media(max-width:1000px){.risk-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.risk-fields{grid-template-columns:1fr}.risk-settings-heading{align-items:start;flex-direction:column}.risk-section{padding:15px}.risk-save{flex-wrap:wrap}}</style>
